const enMeta = {title:'Ian the Barber — Home Barber in Canggu, Bali',description:'Home barber in Canggu, Bali. Ian comes to your villa for fades, scissor cuts and beard trims.',lang:'en'};
const idMeta = {title:'Ian the Barber — Barber Panggilan di Canggu, Bali',description:'Barber panggilan di Canggu, Bali. Ian datang ke vila untuk fade, potong rambut, dan rapikan janggut.',lang:'id'};
const bodyTextNodes = [];
const originalText = new Map();
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
let textNode;
while ((textNode = walker.nextNode())) {
  if (textNode.parentElement && textNode.parentElement.closest('.lang-switch')) continue;
  bodyTextNodes.push(textNode);
  originalText.set(textNode, textNode.nodeValue);
}
const preserveSpace = (value, next) => {
  const m = value.match(/^(\s*)([\s\S]*?)(\s*)$/);
  return m[1] + next + m[3];
};
function setLanguage(lang) {
  const dict = lang === 'id' ? translationsId : null;
  bodyTextNodes.forEach(node => {
    const original = originalText.get(node) || '';
    const trimmed = original.trim();
    if (!trimmed) return;
    const translated = dict && Object.prototype.hasOwnProperty.call(dict, trimmed) ? dict[trimmed] : trimmed;
    node.nodeValue = preserveSpace(original, translated);
  });
  const meta = lang === 'id' ? idMeta : enMeta;
  document.documentElement.lang = meta.lang;
  document.title = meta.title;
  const description = document.querySelector('meta[name="description"]');
  if (description) description.setAttribute('content', meta.description);
  document.querySelectorAll('[data-lang-btn]').forEach(btn => {
    const active = btn.dataset.langBtn === lang;
    btn.setAttribute('aria-pressed', String(active));
  });
  document.querySelector('.map-locate')?.setAttribute('aria-label', lang === 'id' ? 'Pusatkan peta di Canggu' : 'Center map on Canggu');
  document.getElementById('barber-map')?.setAttribute('aria-label', lang === 'id' ? 'Peta Canggu dan area layanan sekitar' : 'Map showing Canggu and nearby service areas');
  document.querySelector('[data-booking-close]')?.setAttribute('aria-label', lang === 'id' ? 'Tutup' : 'Close');
  document.querySelector('.booking-options')?.setAttribute('aria-label', lang === 'id' ? 'Layanan' : 'Services');
  try { localStorage.setItem('ian-lang', lang); } catch (e) {}
}
document.querySelectorAll('[data-lang-btn]').forEach(btn => {
  btn.addEventListener('click', () => setLanguage(btn.dataset.langBtn));
});
let savedLang = 'en';
try { savedLang = localStorage.getItem('ian-lang') === 'id' ? 'id' : 'en'; } catch (e) {}
setLanguage(savedLang);

const nav = document.getElementById('top-nav');
const observer = new IntersectionObserver((entries)=>entries.forEach(entry=>{
  if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}
}),{threshold:.08,rootMargin:'0px 0px -60px 0px'});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));

let lastScrollY = window.scrollY;
let ticking = false;
const updateHeader = () => {
  const y = Math.max(0, window.scrollY);
  nav.classList.toggle('nav-scrolled', y > 18);
  if (y <= 18) {
    nav.classList.remove('nav-hidden');
  } else if (y > lastScrollY + 6) {
    nav.classList.add('nav-hidden');
  } else if (y < lastScrollY - 6) {
    nav.classList.remove('nav-hidden');
  }
  lastScrollY = y;
  ticking = false;
};
window.addEventListener('scroll',()=>{
  if(!ticking){window.requestAnimationFrame(updateHeader);ticking=true;}
},{passive:true});
updateHeader();

// Keep every visual slot occupied even when a demo/remote image is unavailable.
const markMediaEmpty = (img) => {
  img.style.visibility = 'hidden';
  const frame = img.closest('.img-hover, [class*="aspect-4\/5"], [class*="aspect-4\/3"], .media-frame');
  if (frame) frame.classList.add('media-empty');
};
document.querySelectorAll('img').forEach((img) => {
  img.addEventListener('error', () => markMediaEmpty(img), {once:true});
  if (img.complete && img.naturalWidth === 0) markMediaEmpty(img);
});


const bookingModal = document.getElementById('booking-modal');
const bookingContinue = bookingModal?.querySelector('[data-booking-continue]');
const bookingOptions = bookingModal ? Array.from(bookingModal.querySelectorAll('[data-booking-option]')) : [];
let selectedBookingService = null;
let lastBookingTrigger = null;
const bookingServices = {
  'HOME HAIRCUT': {en:'Home Haircut', id:'Potong Rambut'},
  'SKIN FADE': {en:'Skin Fade', id:'Skin Fade'},
  'HAIRCUT & BEARD TRIM': {en:'Haircut & Beard Trim', id:'Potong Rambut & Rapikan Janggut'},
  'BEARD TRIM & LINE-UP': {en:'Beard Trim & Line-up', id:'Rapikan Janggut & Line-up'}
};
const selectBookingService = (key) => {
  selectedBookingService = bookingServices[key] ? key : null;
  bookingOptions.forEach(option => {
    const active = option.dataset.bookingOption === selectedBookingService;
    option.classList.toggle('is-selected', active);
    option.setAttribute('aria-selected', String(active));
  });
  if (bookingContinue) bookingContinue.disabled = !selectedBookingService;
};
const openBookingModal = (preselected = null, trigger = null) => {
  if (!bookingModal) return;
  lastBookingTrigger = trigger || document.activeElement;
  selectBookingService(preselected);
  bookingModal.classList.add('is-open');
  bookingModal.setAttribute('aria-hidden','false');
  document.documentElement.style.overflow = 'hidden';
  bookingModal.querySelector('.booking-close')?.focus();
};
const closeBookingModal = () => {
  if (!bookingModal) return;
  bookingModal.classList.remove('is-open');
  bookingModal.setAttribute('aria-hidden','true');
  document.documentElement.style.overflow = '';
  if (lastBookingTrigger && typeof lastBookingTrigger.focus === 'function') lastBookingTrigger.focus();
  lastBookingTrigger = null;
};
document.querySelectorAll('[data-booking="true"]').forEach(link => {
  link.addEventListener('click', (event) => {
    event.preventDefault();
    openBookingModal(link.dataset.service || null, link);
  });
});
bookingOptions.forEach(option => option.addEventListener('click', () => selectBookingService(option.dataset.bookingOption)));
bookingModal?.querySelector('[data-booking-close]')?.addEventListener('click', closeBookingModal);
bookingModal?.addEventListener('click', (event) => {
  if (event.target === bookingModal) closeBookingModal();
});
document.addEventListener('keydown', (event) => {
  if (!bookingModal?.classList.contains('is-open')) return;
  if (event.key === 'Escape') closeBookingModal();
});
bookingContinue?.addEventListener('click', () => {
  if (!selectedBookingService) return;
  const lang = document.documentElement.lang === 'id' ? 'id' : 'en';
  const service = bookingServices[selectedBookingService][lang];
  const message = lang === 'id'
    ? `Halo Ian, saya mau booking: ${service}. Bisa info jadwal yang tersedia?`
    : `Hi Ian, I'd like to book: ${service}. Could you let me know your availability?`;
  const url = `https://wa.me/6283805877791?text=${encodeURIComponent(message)}`;
  closeBookingModal();
  window.location.href = url;
});

const map = L.map('barber-map',{zoomControl:false,scrollWheelZoom:false,dragging:true}).setView([-8.6478,115.1385],13);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);
L.control.zoom({position:'bottomright'}).addTo(map);
const pinIcon=L.divIcon({className:'',html:'<div class="map-pin"></div>',iconSize:[18,18],iconAnchor:[9,18]});
const spots=[[-8.6478,115.1385,'Canggu'],[-8.6591,115.1458,'Berawa'],[-8.6547,115.1237,'Batu Bolong'],[-8.6468,115.1157,'Pererenan'],[-8.6621,115.1633,'Seminyak']];
spots.forEach(([lat,lng,name],i)=>L.marker([lat,lng],{icon:pinIcon}).addTo(map).bindTooltip(name,{permanent:i===0,direction:'top',offset:[0,-10],className:'barber-tooltip'}));
document.querySelector('.map-locate').addEventListener('click',()=>map.flyTo([-8.6478,115.1385],13,{duration:.7}));
